referenceSolutions.python:
def parcelBudgetFirstQualifyingSlip(drawers, k):
    a=drawers
    out=[]
    dp=[0]*(k+1)
    for weight,value in a:
        for c in range(k,weight-1,-1): dp[c]=max(dp[c],dp[c-weight]+value)
    out=dp
    return next((x for x in out if x>=k),-1)

